package vn.smarttravel.trip.itinerary.controller;
import vn.smarttravel.trip.itinerary.client.*;
import vn.smarttravel.trip.itinerary.service.*;
import java.util.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.http.ResponseEntity;
import static vn.smarttravel.trip.shared.web.ApiValues.*;
@RestController
public class TripController {
 private final TripService service;
 private final DayTravelService travel;
 public TripController(TripService service,DayTravelService travel){this.service=service;this.travel=travel;}
 private UUID actor(Jwt jwt,String scope){var scopes=jwt.getClaimAsString("scope");require(scopes!=null&&Arrays.asList(scopes.split(" ")).contains(scope),403,"FORBIDDEN");return id(jwt.getSubject());}
 private ResponseEntity<Object> ok(Object body,int status){var builder=ResponseEntity.status(status).cacheControl(org.springframework.http.CacheControl.noStore());if(body instanceof Map<?,?>m&&m.get("version")!=null)builder.eTag(m.get("version").toString());var attributes=org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();if(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes request){String path=request.getRequest().getRequestURI();if(path.startsWith("/api/v1/trips/")&&status!=204){String trip=path.substring(14).split("/")[0];var auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(auth.getPrincipal() instanceof Jwt jwt){var warnings=service.warnings(id(trip),id(jwt.getSubject()));if(!warnings.isEmpty())builder.header("X-Trip-Warnings",String.join(",",warnings));}}}return builder.body(body);}
 @GetMapping("/api/v1/me/trips") public Object list(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String cursor){return ok(service.list(actor(jwt,"trip:read"),limit,cursor),200);}
 @PostMapping("/api/v1/me/trips") public Object create(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){return ok(service.create(actor(jwt,"trip:write"),b),201);}
 @GetMapping("/api/v1/trips/{trip}") public Object get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip){return ok(service.get(trip,actor(jwt,"trip:read")),200);}
 @PatchMapping("/api/v1/trips/{trip}") public Object patch(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.patch(trip,actor(jwt,"trip:write"),v,b),200);}
 @DeleteMapping("/api/v1/trips/{trip}") public Object delete(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v){service.delete(trip,actor(jwt,"trip:write"),v);return ok(null,204);}
 @PutMapping("/api/v1/trips/{trip}/state") public Object state(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.state(trip,actor(jwt,"trip:write"),v,text(b,"state",20)),200);}
 @GetMapping("/api/v1/trips/{trip}/destinations") public Object listdestinations(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String cursor){return ok(service.paginate(service.segments(trip,actor(jwt,"trip:read"),null),limit,cursor),200);}
 @GetMapping("/api/v1/trips/{trip}/destinations/{segment}") public Object getdestinations(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID segment){return ok(service.segments(trip,actor(jwt,"trip:read"),segment),200);}
 @PostMapping("/api/v1/trips/{trip}/destinations") public Object createdestinations(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.segment(trip,actor(jwt,"trip:write"),null,v,b),201);}
 @PatchMapping("/api/v1/trips/{trip}/destinations/{segment}") public Object patchdestinations(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID segment,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.segment(trip,actor(jwt,"trip:write"),segment,v,b),200);}
 @DeleteMapping("/api/v1/trips/{trip}/destinations/{segment}") public Object deletedestinations(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID segment,@RequestHeader(value="If-Match",required=false)String v){service.deleteSegment(trip,actor(jwt,"trip:write"),segment,v);return ok(null,204);}
 @GetMapping("/api/v1/trips/{trip}/days") public Object listdays(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String cursor){return ok(service.paginate(service.days(trip,actor(jwt,"trip:read"),null),limit,cursor),200);}
 @GetMapping("/api/v1/trips/{trip}/days/{day}") public Object getdays(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day){return ok(service.days(trip,actor(jwt,"trip:read"),day),200);}
 @PostMapping("/api/v1/trips/{trip}/days") public Object createdays(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.day(trip,actor(jwt,"trip:write"),null,v,b),201);}
 @PatchMapping("/api/v1/trips/{trip}/days/{day}") public Object patchdays(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.day(trip,actor(jwt,"trip:write"),day,v,b),200);}
 @DeleteMapping("/api/v1/trips/{trip}/days/{day}") public Object deletedays(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@RequestHeader(value="If-Match",required=false)String v){service.deleteDay(trip,actor(jwt,"trip:write"),day,v);return ok(null,204);}
 @GetMapping("/api/v1/trips/{trip}/transfers") public Object listtransfers(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String cursor){return ok(service.paginate(service.transfers(trip,actor(jwt,"trip:read"),null),limit,cursor),200);}
 @GetMapping("/api/v1/trips/{trip}/transfers/{transfer}") public Object gettransfers(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID transfer){return ok(service.transfers(trip,actor(jwt,"trip:read"),transfer),200);}
 @PostMapping("/api/v1/trips/{trip}/transfers") public Object createtransfers(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.transfer(trip,actor(jwt,"trip:write"),null,v,b,false),201);}
 @PatchMapping("/api/v1/trips/{trip}/transfers/{transfer}") public Object patchtransfers(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID transfer,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.transfer(trip,actor(jwt,"trip:write"),transfer,v,b,false),200);}
 @DeleteMapping("/api/v1/trips/{trip}/transfers/{transfer}") public Object deletetransfers(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID transfer,@RequestHeader(value="If-Match",required=false)String v){service.deleteTransfer(trip,actor(jwt,"trip:write"),transfer,v);return ok(null,204);}
 @GetMapping("/api/v1/trips/{trip}/days/{day}/items") public Object items(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String cursor){return ok(service.paginate(service.items(trip,actor(jwt,"trip:read"),day,null),limit,cursor),200);}
 @GetMapping("/api/v1/trips/{trip}/days/{day}/items/{item}") public Object item(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@PathVariable UUID item){return ok(service.items(trip,actor(jwt,"trip:read"),day,item),200);}
 @PostMapping("/api/v1/trips/{trip}/days/{day}/items") public Object add(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@RequestHeader(value="If-Match",required=false)String v,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object>b){return ok(service.addItem(trip,actor(jwt,"trip:write"),day,v,key,b),201);}
 @PatchMapping("/api/v1/trips/{trip}/days/{day}/items/{item}") public Object patchItem(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@PathVariable UUID item,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.patchItem(trip,actor(jwt,"trip:write"),day,item,v,b),200);}
 @DeleteMapping("/api/v1/trips/{trip}/days/{day}/items/{item}") public Object deleteItem(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@PathVariable UUID item,@RequestHeader(value="If-Match",required=false)String v){service.deleteItem(trip,actor(jwt,"trip:write"),day,item,v);return ok(null,204);}
 @PutMapping("/api/v1/trips/{trip}/days/{day}/items/order") public Object order(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.order(trip,actor(jwt,"trip:write"),day,v,ids(b)),200);}
 @PostMapping("/api/v1/trips/{trip}/snapshots/refresh") public Object refresh(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.refresh(trip,actor(jwt,"trip:write"),v,ids(b)),202);}
 @PostMapping("/api/v1/trips/{trip}/route-estimates") public Object estimate(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(service.transfer(trip,actor(jwt,"trip:write"),null,v,b,true),200);}
 @GetMapping("/api/v1/trips/{trip}/days/{day}/travel-legs") public Object legs(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day){return ok(travel.list(trip,actor(jwt,"trip:read"),day),200);}
 @PatchMapping("/api/v1/trips/{trip}/days/{day}/travel-legs/{leg}") public Object mode(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID trip,@PathVariable UUID day,@PathVariable UUID leg,@RequestHeader(value="If-Match",required=false)String v,@RequestBody Map<String,Object>b){return ok(travel.mode(trip,actor(jwt,"trip:write"),day,leg,v,b),200);}
 private List<UUID> ids(Map<String,Object>b){require(b.get("item_ids") instanceof List<?>,400,"INVALID_ITEM_IDS");return ((List<?>)b.get("item_ids")).stream().map(vn.smarttravel.trip.shared.web.ApiValues::id).toList();}
}
